// KhmerMath service worker (generated by tools/build.py)
const CACHE = 'km-da3161f290';
self.addEventListener('install', (e) => { e.waitUntil(self.skipWaiting()); });
self.addEventListener('activate', (e) => { e.waitUntil((async () => { for (const k of await caches.keys()) if (k !== CACHE && k.startsWith('km-')) await caches.delete(k); await self.clients.claim(); })()); });
self.addEventListener('fetch', (e) => {
  const req = e.request, url = new URL(req.url);
  if (req.method !== 'GET' || url.origin !== location.origin || /\.(mp4|webm|mov)$/i.test(url.pathname) || req.headers.has('range')) return;
  if (req.mode === 'navigate') {                         // pages: fresh when online, last copy when offline
    e.respondWith((async () => { try { const r = await fetch(req); if (r.ok) (await caches.open(CACHE)).put(req, r.clone()); return r; } catch { return (await caches.match(req)) || (await caches.match('/404.html')) || Response.error(); } })());
    return;
  }
  e.respondWith((async () => {                           // files: from the cache, refreshed in the background
    const hit = await caches.match(req);
    const net = fetch(req).then((r) => { if (r.ok) caches.open(CACHE).then((c) => c.put(req, r.clone())); return r; }).catch(() => null);
    return hit || (await net) || Response.error();
  })());
});
